# ruff: noqa: E501
from fastapi import APIRouter
from fastapi.responses import HTMLResponse

from newsintel.api.dependencies import ViewerAuth
from newsintel.api.ui import COMMON_JS, render_app_page
from newsintel.domain.access import Permission

router = APIRouter(tags=["search-dashboard"])


@router.get("/search", response_class=HTMLResponse)
async def search_dashboard(auth: ViewerAuth) -> str:
    role = getattr(getattr(auth, "role", None), "value", "viewer")
    can_save = Permission.CLAIMS_VIEW.value in auth.permissions
    body = r"""
<section class="page-head">
  <div>
    <div class="eyebrow">Search the archive</div>
    <h1>Intelligence Search</h1>
    <p class="lead">Find an event, report, claim or organisation. Results link to the original reporting and its recorded context.</p>
  </div>
  <div class="toolbar"><span id="searchStatus" class="muted small" aria-live="polite">Enter at least 2 characters</span><button id="saveSearchBtn" class="secondary" type="button" hidden>Save search</button></div>
</section>
<section class="panel flat stack">
  <div class="search-hero">
    <label class="sr-only" for="globalSearch">Search intelligence</label>
    <input id="globalSearch" type="search" autocomplete="off" spellcheck="false" placeholder="Search events, reporting and claims…" />
    <button id="searchBtn" type="button">Search</button>
  </div>
  <div class="muted small">Searches stored database content, including current reports and approved entity names. Use quotes for exact phrases. Press <kbd>/</kbd> to focus search.</div>
  <div id="assistBox" class="assist-box" hidden aria-live="polite"></div>
</section>
<section class="panel flat stack" style="margin-top:14px" aria-label="Search filters">
  <div class="filters" id="typeFilters">
    <button class="filter-chip active" data-type="all" type="button">All</button>
    <button class="filter-chip" data-type="event" type="button">Events</button>
    <button class="filter-chip" data-type="article" type="button">Articles</button>
    <button class="filter-chip" data-type="claim" type="button">Claims</button>
    <button class="filter-chip" data-type="entity" type="button">Entities</button>
  </div>
  <div class="search-filter-grid">
    <label>Language<input id="filterLanguage" maxlength="35" placeholder="en, hi…" /></label>
    <label>Publisher<input id="filterPublisher" maxlength="200" placeholder="Reuters, PTI…" /></label>
    <label>Event lifecycle<select id="filterLifecycle"><option value="">Any lifecycle</option><option value="developing">Developing</option><option value="stable">Stable</option><option value="closed">Closed</option></select></label>
    <label>From<input id="filterFrom" type="date" /></label>
    <label>To<input id="filterTo" type="date" /></label>
    <div class="filter-actions"><button id="applyFilters" class="secondary" type="button">Apply filters</button><button id="clearFilters" class="ghost" type="button">Clear</button></div>
  </div>
</section>
<dialog id="saveSearchDialog"><form method="dialog" class="dialog-card"><div class="section-head"><h2>Save this search</h2><button class="ghost" value="cancel" aria-label="Close">Close</button></div><label>Name<input id="savedSearchName" maxlength="200" placeholder="Coal policy updates" /></label><label>Attach to investigation<select id="savedSearchInvestigation"><option value="">No investigation</option></select></label><div class="muted small">The current result type and filter values are saved with the query and reused by scheduled monitoring.</div><div class="toolbar" style="margin-top:12px"><button id="confirmSaveSearch" type="button">Save search</button></div></form></dialog>
<section class="search-metrics" style="margin-top:18px" id="searchMetrics">
  <div class="metric"><div class="label">Matching corpus</div><div class="value" id="mTotal">0</div></div>
  <div class="metric"><div class="label">Events</div><div class="value" id="mEvents">0</div></div>
  <div class="metric"><div class="label">Articles</div><div class="value" id="mArticles">0</div></div>
  <div class="metric"><div class="label">Claims</div><div class="value" id="mClaims">—</div><div class="hint" id="claimSearchHint">Depends on access</div></div>
  <div class="metric"><div class="label">Entities</div><div class="value" id="mEntities">—</div><div class="hint" id="entitySearchHint">Analyst access</div></div>
</section>
<section style="margin-top:18px">
  <div class="section-head"><h2>Results</h2><span id="resultCount" class="muted small"></span></div>
  <div id="searchResults" class="article-list" aria-live="polite"><div class="empty"><b>Search the intelligence corpus.</b><div class="small" style="margin-top:6px">Results stay separated by event, article and claim so evidence semantics remain clear.</div></div></div>
  <div class="load-more-row"><button id="loadMoreBtn" class="secondary" type="button" hidden>Load more results</button><span id="snapshotNote" class="muted small"></span></div>
</section>
"""
    extra_css = r"""
.search-hero{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px}.search-hero input{font-size:17px;padding:14px 15px}.search-filter-grid{display:grid;grid-template-columns:repeat(5,minmax(120px,1fr));gap:10px;align-items:end}.search-metrics{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px}.search-filter-grid label{display:grid;gap:5px;font-size:12px;font-weight:700;color:var(--muted)}.filter-actions{display:flex;gap:8px;align-items:end}.search-result{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:18px;padding:18px;border:1px solid var(--line);border-radius:14px;background:var(--surface);box-shadow:0 1px 2px rgba(20,31,55,.03)}.search-result h2{font-size:18px;line-height:1.34;margin:7px 0}.search-result p{margin:8px 0 0;line-height:1.58}.search-result-side{text-align:right;min-width:130px}.result-type{font-size:11px;font-weight:850;letter-spacing:.08em;text-transform:uppercase;color:var(--brand)}.rank-note{font-size:11px;color:var(--muted);margin-top:5px}.load-more-row{display:flex;justify-content:center;align-items:center;gap:12px;margin:18px 0 8px}kbd{border:1px solid var(--line-strong);background:var(--surface-2);border-radius:5px;padding:1px 5px;font:inherit;font-size:11px}.assist-box{border-top:1px solid var(--line);padding-top:10px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}.assist-box[hidden]{display:none}.assist-suggestion{font-size:12px}.assist-reason{width:100%;font-size:11px;color:var(--muted)}.dialog-card{min-width:min(520px,calc(100vw - 36px));display:grid;gap:12px}dialog{border:1px solid var(--line);border-radius:16px;background:var(--surface);color:var(--text);box-shadow:var(--shadow);padding:20px}dialog::backdrop{background:rgba(10,18,35,.5)}@media(max-width:1000px){.search-filter-grid,.search-metrics{grid-template-columns:repeat(2,minmax(140px,1fr))}}@media(max-width:700px){.search-hero{grid-template-columns:1fr}.search-result{grid-template-columns:1fr}.search-result-side{text-align:left}.search-filter-grid,.search-metrics{grid-template-columns:1fr}.filter-actions{align-items:stretch}}
"""
    can_save_js = "true" if can_save else "false"
    scripts = f"""<script>{COMMON_JS}
let searchData={{results:[],counts:{{}},searched_claims:false,next_cursor:null,snapshot_at:null,search_mode:'postgres_fts',deployment_variant:'lexical',deployment_exposure_id:null}};let activeType='all';let loading=false;const canSaveSearch={can_save_js};const input=document.getElementById('globalSearch');const resultBox=document.getElementById('searchResults');
function typeKind(type){{return type==='event'?'info':type==='claim'?'warn':type==='entity'?'good':'neutral'}}
function resultHref(item){{if(item.result_type==='event')return `/events/${{niEsc(item.event_id||item.id)}}/intelligence`;if(item.result_type==='claim')return `/claims/${{niEsc(item.id)}}/investigation`;if(item.result_type==='entity')return `/entities/${{niEsc(item.id)}}/intelligence`;if(item.article_id)return `/articles/${{niEsc(item.article_id)}}/intelligence`;return '#'}}
function metaText(item){{const m=item.metadata||{{}};if(item.result_type==='event')return [niTitle(m.lifecycle_status||''),niTitle(m.assignment_status||'')].filter(Boolean).join(' · ');if(item.result_type==='article')return [m.publisher,m.language].filter(Boolean).join(' · ');if(item.result_type==='claim')return [niTitle(m.claim_type||''),niTitle(m.verification_label||'unverified'),m.publisher].filter(Boolean).join(' · ');if(item.result_type==='entity')return [niTitle(m.entity_type||''),m.country_code,m.matched_alias?`Alias: ${{m.matched_alias}}`:null].filter(Boolean).join(' · ');return ''}}
function currentFilters(){{return {{result_type:activeType,language:document.getElementById('filterLanguage').value.trim(),publisher:document.getElementById('filterPublisher').value.trim(),lifecycle_status:document.getElementById('filterLifecycle').value,from_date:document.getElementById('filterFrom').value,to_date:document.getElementById('filterTo').value}}}}
function isoStart(value){{return value?`${{value}}T00:00:00Z`:''}}function isoEnd(value){{return value?`${{value}}T23:59:59.999Z`:''}}
function buildApiUrl(cursor=''){{const q=input.value.trim(),f=currentFilters(),p=new URLSearchParams({{q,limit:'30',result_type:f.result_type}});if(cursor)p.set('cursor',cursor);if(f.language)p.set('language',f.language);if(f.publisher)p.set('publisher',f.publisher);if(f.lifecycle_status)p.set('lifecycle_status',f.lifecycle_status);if(f.from_date)p.set('from_date',isoStart(f.from_date));if(f.to_date)p.set('to_date',isoEnd(f.to_date));return `/api/v1/search?${{p.toString()}}`}}
function syncLocation(){{const q=input.value.trim(),f=currentFilters(),url=new URL(location.href);[['q',q],['type',f.result_type==='all'?'':f.result_type],['language',f.language],['publisher',f.publisher],['lifecycle_status',f.lifecycle_status],['from_date',f.from_date],['to_date',f.to_date]].forEach(([k,v])=>v?url.searchParams.set(k,v):url.searchParams.delete(k));history.replaceState(null,'',url)}}
function resultKey(item){{return `${{item.result_type}}:${{item.id}}`}}
function renderSearch(){{const rows=searchData.results;const total=Object.values(searchData.counts||{{}}).reduce((a,b)=>a+Number(b||0),0);document.getElementById('resultCount').textContent=`${{rows.length}} loaded · ${{total}} matching`;document.getElementById('mTotal').textContent=total;document.getElementById('mEvents').textContent=searchData.counts.event||0;document.getElementById('mArticles').textContent=searchData.counts.article||0;document.getElementById('mClaims').textContent=searchData.searched_claims?(searchData.counts.claim||0):'—';document.getElementById('claimSearchHint').textContent=searchData.searched_claims?'Indexed claim corpus searched':'Claim access required';document.getElementById('mEntities').textContent=searchData.searched_entities?(searchData.counts.entity||0):'—';document.getElementById('entitySearchHint').textContent=searchData.searched_entities?'Canonical entity registry searched':'Analyst access required';document.querySelector('[data-type="claim"]').hidden=!searchData.searched_claims;document.querySelector('[data-type="entity"]').hidden=!searchData.searched_entities;document.getElementById('loadMoreBtn').hidden=!searchData.next_cursor;document.getElementById('snapshotNote').textContent=searchData.snapshot_at?`Results as of ${{niDate(searchData.snapshot_at)}} · Ranked by relevance`:'';if(!rows.length){{resultBox.innerHTML='<div class="empty"><b>No matching results.</b><div class="small" style="margin-top:6px">Try broader terms, remove a filter, or use web-search operators such as quotes or OR.</div></div>';return}}resultBox.innerHTML=rows.map((item,idx)=>`<article class="search-result"><div><div class="pill-row">${{niPill(niTitle(item.result_type),typeKind(item.result_type))}}</div><h2><a class="deployment-result-link" data-result-type="${{niEsc(item.result_type)}}" data-result-id="${{niEsc(item.id)}}" data-exposure-id="${{niEsc(item._exposure_id||'')}}" data-rank="${{item._served_rank||idx+1}}" href="${{resultHref(item)}}">${{niEsc(item.title)}}</a></h2>${{item.snippet?`<p class="muted">${{niEsc(item.snippet)}}</p>`:''}}<div class="muted small" style="margin-top:10px">${{niEsc(metaText(item))}}${{item.occurred_at?` · ${{niDate(item.occurred_at)}}`:''}}</div><div class="rank-note">${{item._deployment_variant==='hybrid_canary'?'Experimental article ordering is active for this search.':'Matched text in stored reports.'}}</div></div><div class="search-result-side"><div class="result-type">${{niEsc(item.result_type)}}</div><div style="margin-top:12px"><a class="button secondary deployment-result-link" data-result-type="${{niEsc(item.result_type)}}" data-result-id="${{niEsc(item.id)}}" data-exposure-id="${{niEsc(item._exposure_id||'')}}" data-rank="${{item._served_rank||idx+1}}" href="${{resultHref(item)}}">Open</a></div>${{item.event_id&&item.result_type!=='event'?`<div style="margin-top:8px"><a class="small" href="/events/${{niEsc(item.event_id)}}/intelligence">Open event</a></div>`:''}}</div></article>`).join('');document.querySelectorAll('.deployment-result-link').forEach(link=>link.addEventListener('click',()=>recordDeploymentOpen(link)))}}
function recordDeploymentOpen(link){{const exposure=link.dataset.exposureId;if(!exposure)return;const payload={{action:'open_result',exposure_id:exposure,result_type:link.dataset.resultType,result_id:link.dataset.resultId,rank:Number(link.dataset.rank)||null}};fetch('/api/v1/search/deployment/outcome',{{method:'POST',credentials:'same-origin',keepalive:true,headers:{{'Content-Type':'application/json','X-CSRF-Token':niCsrf()}},body:JSON.stringify(payload)}}).catch(()=>{{}})}}
async function runSearch({{append=false}}={{}}){{if(loading)return;const q=input.value.trim();syncLocation();if(q.length<2){{searchData={{results:[],counts:{{}},searched_claims:false,next_cursor:null,snapshot_at:null,search_mode:'postgres_fts',deployment_variant:'lexical',deployment_exposure_id:null}};document.getElementById('searchStatus').textContent='Enter at least 2 characters';resultBox.innerHTML='<div class="empty">Enter at least 2 characters to search.</div>';renderSearch();return}}loading=true;document.getElementById('searchBtn').disabled=true;document.getElementById('loadMoreBtn').disabled=true;document.getElementById('searchStatus').textContent=append?'Loading next ranked page…':'Searching indexed corpus…';if(!append)resultBox.innerHTML='<div class="skeleton" style="height:130px"></div><div class="skeleton" style="height:130px"></div>';try{{const data=await niApi(buildApiUrl(append?searchData.next_cursor||'':''));data.results=(data.results||[]).map((x,i)=>({{...x,_exposure_id:data.deployment_exposure_id||null,_deployment_variant:data.deployment_variant||'lexical',_served_rank:i+1}}));if(append){{const seen=new Set(searchData.results.map(resultKey));searchData.results=[...searchData.results,...data.results.filter(x=>!seen.has(resultKey(x)))];if(Object.keys(data.counts||{{}}).length)searchData.counts=data.counts;searchData.next_cursor=data.next_cursor;searchData.snapshot_at=data.snapshot_at;searchData.searched_claims=data.searched_claims;searchData.searched_entities=data.searched_entities}}else{{searchData=data}}document.getElementById('searchStatus').textContent=`Indexed search completed ${{new Date().toLocaleTimeString()}}`;renderSearch()}}catch(err){{document.getElementById('searchStatus').textContent='Search unavailable';if(!append)resultBox.innerHTML=`<div class="error-box"><b>Could not search the corpus.</b><div class="small" style="margin-top:5px">${{niEsc(err.message)}}</div></div>`;else niToast(err.message,'bad')}}finally{{loading=false;document.getElementById('searchBtn').disabled=false;document.getElementById('loadMoreBtn').disabled=false}}}}
async function loadAssistance(){{const q=input.value.trim(),box=document.getElementById('assistBox');if(q.length<3){{box.hidden=true;box.innerHTML='';return}}try{{const d=await niApi(`/api/v1/search/assist?q=${{encodeURIComponent(q)}}&limit=6`);const parts=[];if(d.language_filter_hint&&!document.getElementById('filterLanguage').value)parts.push(`<button type="button" class="ghost assist-suggestion" data-language="${{niEsc(d.language_filter_hint)}}">Filter language: ${{niEsc(d.language_filter_hint)}}</button>`);for(const item of d.suggestions||[])parts.push(`<button type="button" class="secondary assist-suggestion" data-replacement="${{niEsc(item.replacement)}}" title="${{niEsc(item.reason)}}">Did you mean ${{niEsc(item.label)}}?</button>`);if(!parts.length){{box.hidden=true;box.innerHTML='';return}}box.innerHTML=`<span class="muted small">Suggestions (click to use):</span>${{parts.join('')}}`;box.hidden=false;box.querySelectorAll('[data-replacement]').forEach(btn=>btn.onclick=()=>{{input.value=btn.dataset.replacement||q;box.hidden=true;runSearch()}});box.querySelectorAll('[data-language]').forEach(btn=>btn.onclick=()=>{{document.getElementById('filterLanguage').value=btn.dataset.language||'';box.hidden=true;runSearch()}})}}catch(_e){{box.hidden=true;box.innerHTML=''}}}}
async function openSaveSearch(){{if(!canSaveSearch)return;const q=input.value.trim();if(q.length<2){{niToast('Run a search before saving it','bad');return}}const select=document.getElementById('savedSearchInvestigation');select.innerHTML='<option value="">No investigation</option>';try{{const rows=await niApi('/api/v1/investigations');select.innerHTML+=rows.filter(x=>x.status==='active'&&x.access_role!=='reader').map(x=>`<option value="${{x.id}}">${{niEsc(x.title)}}</option>`).join('')}}catch(e){{niToast(e.message,'bad')}}document.getElementById('savedSearchName').value=q.slice(0,80);document.getElementById('saveSearchDialog').showModal()}}
async function saveCurrentSearch(){{const q=input.value.trim(),name=document.getElementById('savedSearchName').value.trim(),investigationId=document.getElementById('savedSearchInvestigation').value,f=currentFilters();if(name.length<2){{niToast('Enter a name for the saved search','bad');return}}const filters={{result_type:f.result_type,language:f.language||null,publisher:f.publisher||null,lifecycle_status:f.lifecycle_status||null,from_date:f.from_date?isoStart(f.from_date):null,to_date:f.to_date?isoEnd(f.to_date):null}};try{{await niApi('/api/v1/saved-searches',{{method:'POST',body:JSON.stringify({{name,query:q,investigation_id:investigationId||null,filters}})}});document.getElementById('saveSearchDialog').close();niToast('Indexed search saved','good')}}catch(e){{niToast(e.message,'bad')}}}}
function setActiveType(type){{activeType=['event','article','claim','entity'].includes(type)?type:'all';document.querySelectorAll('#typeFilters [data-type]').forEach(x=>x.classList.toggle('active',x.dataset.type===activeType))}}
if(!canSaveSearch){{document.querySelector('[data-type="claim"]').hidden=true;document.querySelector('[data-type="entity"]').hidden=true}}
if(canSaveSearch){{document.getElementById('saveSearchBtn').hidden=false;document.getElementById('saveSearchBtn').addEventListener('click',openSaveSearch);document.getElementById('confirmSaveSearch').addEventListener('click',saveCurrentSearch)}}
const delayed=niDebounce(()=>runSearch(),320);const assistDelayed=niDebounce(()=>loadAssistance(),480);input.addEventListener('input',delayed);input.addEventListener('input',assistDelayed);document.getElementById('searchBtn').addEventListener('click',()=>runSearch());document.getElementById('loadMoreBtn').addEventListener('click',()=>runSearch({{append:true}}));input.addEventListener('keydown',e=>{{if(e.key==='Enter'){{e.preventDefault();runSearch()}}}});document.querySelectorAll('#typeFilters [data-type]').forEach(btn=>btn.addEventListener('click',()=>{{setActiveType(btn.dataset.type);runSearch()}}));document.getElementById('applyFilters').addEventListener('click',()=>runSearch());document.getElementById('clearFilters').addEventListener('click',()=>{{document.getElementById('filterLanguage').value='';document.getElementById('filterPublisher').value='';document.getElementById('filterLifecycle').value='';document.getElementById('filterFrom').value='';document.getElementById('filterTo').value='';runSearch()}});document.addEventListener('keydown',e=>{{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){{e.preventDefault();input.focus()}}}});
const initialParams=new URLSearchParams(location.search);setActiveType(initialParams.get('type')||'all');document.getElementById('filterLanguage').value=initialParams.get('language')||'';document.getElementById('filterPublisher').value=initialParams.get('publisher')||'';document.getElementById('filterLifecycle').value=initialParams.get('lifecycle_status')||'';document.getElementById('filterFrom').value=(initialParams.get('from_date')||'').slice(0,10);document.getElementById('filterTo').value=(initialParams.get('to_date')||'').slice(0,10);const initial=initialParams.get('q')||'';if(initial){{input.value=initial;runSearch()}}
</script>"""
    return render_app_page(title="Intelligence Search", body=body, active="search", role=role, scripts=scripts, extra_css=extra_css)
